import{_ as a,o as t,c as r,a4 as s}from"./chunks/framework.CmuCl-jw.js";const h=JSON.parse('{"title":"Storage Credentials Security","description":"","frontmatter":{},"headers":[],"relativePath":"apps/data/credentials-security.md","filePath":"apps/data/credentials-security.md"}'),o={name:"apps/data/credentials-security.md"};function n(i,e,c,l,d,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="storage-credentials-security" tabindex="-1">Storage Credentials Security <a class="header-anchor" href="#storage-credentials-security" aria-label="Permalink to “Storage Credentials Security”">​</a></h1><p>When you attach an <a href="./external-storages">external storage</a>, Arcsecond.local needs its credentials to read from it. Here is how those credentials are kept safe:</p><ul><li>Credentials leave the browser already encrypted, and reach the Arcsecond.local backend over HTTPS.</li><li>They are stored in an <strong>encrypted field</strong> in the database. The field encryption key (<code>FIELD_ENCRYPTION_KEY</code>) lives in your install&#39;s <code>.env</code> file, outside the database itself — so a database dump alone never exposes them.</li><li>No URL route exposes these credentials, and they never appear in any other Arcsecond resource, even to authenticated users, even to the storage owner.</li><li>No credentials of any kind appear in the (private or public) source code.</li><li>The database is backed up hourly (see <a href="/local/backups">Backups</a>); keep those dumps and your <code>.env</code> on separately-permissioned storage, since together they would unseal the encrypted fields.</li></ul><p>Because Arcsecond.local runs on <strong>your own infrastructure</strong>, these credentials never leave your machines.</p><p>Do not hesitate to contact us for any additional question by <a href="mailto:team@arcsecond.io" target="_blank" rel="noreferrer">email</a>, or <a href="https://join.slack.com/t/arcsecond-io/shared_invite/zt-yvsehzjl-jExYLVWzwuslMJum7r2GiA" target="_blank" rel="noreferrer">Slack</a>.</p>',5)])])}const y=a(o,[["render",n]]);export{h as __pageData,y as default};
